                    raise ValueError(
                        "pow backward intermediate must be finite"
                    )
                product = grad_values[i] * y_value * log_base
                if not math.isfinite(product):
                    raise ValueError(
                        "pow backward intermediate must be finite"
                    )
                db_values[i] = product
            if b_vector:
                contributions.append((parent_other, db_values))
            else:
                total = 0.0
