            scaled = grad * 2.0
            if not math.isfinite(scaled):
                raise ValueError(
                    "mse_loss backward intermediate must be finite"
                )
            product = scaled * r_i
            if not math.isfinite(product):
                raise ValueError(
                    "mse_loss backward intermediate must be finite"
                )
